INSERT INTO stage_events (qid, title, summary, start_year, start_month, start_day, end_year, end_month, end_day, precision, display_date, importance, url) VALUES
  ('Q705553', 'Majimaji War', 'The Maji Maji Rebellion (German: Maji-Maji-Aufstand, Swahili: Vita vya Maji Maji) was an armed rebellion of Africans against German colonial rule in German East Africa (modern-day Tanzania). The war was triggered by German colonial policies designed to force the indigenous population to grow cotton for export.', 1905, 7, NULL, 1907, 8, NULL, 'month', 'July 1905 – August 1907', 64, 'https://en.wikipedia.org/wiki/Maji_Maji_Rebellion'),
  ('Q704921', 'Battle of Tanga', 'The Battle of Tanga, also known as the Battle of the Bees, was an unsuccessful invasion of the Port of Tanga in German East Africa by the British Indian Expeditionary Force "B" on 3–5 November 1914 during World War I. Under the command of the Major-General Arthur Aitken, British forces attacked Tanga in concert with Indian Expeditionary Force "C", which concomitantly attempted to capture Longido. The battle was the first major engagement of the East African campaign and saw Aitken''s troops defeated by a smaller force of German Schutztruppen under Paul von Lettow-Vorbeck and forced to retreat.', 1914, 11, 3, 1914, 11, 5, 'day', '3 November 1914 – 5 November 1914', 62, 'https://en.wikipedia.org/wiki/Battle_of_Tanga'),
  ('Q705571', 'East African Campaign', 'The East African campaign in World War I was a series of battles and guerrilla actions, which started in German East Africa (GEA) and spread to portions of Mozambique, Rhodesia, British East Africa, Uganda, and the Belgian Congo. The campaign all but ended in German East Africa in November 1917 when the Germans entered Mozambique and continued the campaign living off Portuguese supplies.', 1914, 8, 3, 1918, 11, 25, 'day', '3 August 1914 – 25 November 1918', 58, 'https://en.wikipedia.org/wiki/East_African_campaign_(World_War_I)'),
  ('Q1174179', 'Battle of Jassin', 'The Battle of Jassin (also known as the Battle of Yasin, the Battle of Jasin, the Battle of Jasini or the Battle of Jassini) was a World War I battle that took place on 18– 19 January 1915 at Jassin on the German East African side of the border with British East Africa between a German Schutztruppe force and British and Indian troops. Jassin had been occupied by the British in order to secure the border between British East Africa and German territory, but was weakly defended by a garrison of four companies of Indian troops, commanded by Colonel Raghbir Singh and numbering a little over 300…', 1915, 1, 18, 1915, 1, 19, 'day', '18 January 1915 – 19 January 1915', 52, 'https://en.wikipedia.org/wiki/Battle_of_Jassin'),
  ('Q2888212', 'Battle of Bukoba', 'The Battle of Bukoba was the first victory for Entente forces in German East Africa, coming after the disastrous battles of Tanga and Jassin. The British objective was the destruction of the Bukoba wireless station.', 1915, 6, 21, 1915, 6, 23, 'day', '21 June 1915 – 23 June 1915', 41, 'https://en.wikipedia.org/wiki/Battle_of_Bukoba'),
  ('Q20724066', 'Battle of Tabora', 'The Battle of Tabora (French: Bataille de Tabora; 8–19 September 1916) was a military action which occurred around the town of Tabora in the north-west of German East Africa (modern-day Tanzania) during World War I. The engagement was part of the East Africa Campaign and was the culmination of the Tabora Offensive in which a Belgian force from the Belgian Congo crossed the border and captured the settlement of Kigoma and Tabora (the largest town in the interior of the German colony), pushing the German colonial army back. The victory not only left much of the Ruanda-Urundi territory under…', 1916, 9, 8, 1916, 9, 19, 'day', '8 September 1916 – 19 September 1916', 43, 'https://en.wikipedia.org/wiki/Battle_of_Tabora'),
  ('Q18164062', 'Gombe Chimpanzee War', 'The Gombe Chimpanzee War, also known as the Four-Year War, was a violent conflict between two communities of chimpanzees in Gombe Stream National Park in the Kigoma region of Tanzania between 1974 and 1978. The two groups were once unified in the Kasakela community.', 1974, NULL, NULL, 1978, 6, 5, 'year', '1974 – 5 June 1978', 63, 'https://en.wikipedia.org/wiki/Gombe_Chimpanzee_War'),
  ('Q202465', 'Uganda–Tanzania War', 'The Uganda–Tanzania War, known in Tanzania as the Kagera War (Swahili: Vita vya Kagera) and in Uganda as the 1979 Liberation War, was fought between Uganda and Tanzania from October 1978 until June 1979 and led to the overthrow of Ugandan President Idi Amin. The war was preceded by a deterioration of relations between Uganda and Tanzania following Amin''s 1971 overthrow of President Milton Obote, who was close to the President of Tanzania, Julius Nyerere.', 1979, 6, 3, 1979, 6, 3, 'day', '3 June 1979', 69, 'https://en.wikipedia.org/wiki/Uganda%E2%80%93Tanzania_War'),
  ('Q130754', '2004 Indian Ocean earthquake', 'On 26 December 2004, at 07:58:53 local time (UTC+7), a Mw 9.2–9.3 earthquake struck with its epicenter off the west coast of Aceh, in northern Sumatra, Indonesia. The undersea megathrust earthquake, known in the scientific community as the Sumatra–Andaman earthquake, was caused by a rupture along the fault boundary between the Burma plate and the Indian plate, and reached a maximum Mercalli intensity of IX in some areas.', 2004, 12, 26, NULL, NULL, NULL, 'day', '26 December 2004', 85, 'https://en.wikipedia.org/wiki/2004_Indian_Ocean_earthquake_and_tsunami'),
  ('Q26847140', '2016 Tanzanian earthquake', 'A magnitude 5.9 earthquake struck Tanzania 27 km (17 mi) east northeast of Nsunga, Kagera Region on 10 September at a depth of 40 km (25 mi). The shock had a maximum intensity of VII (Very strong).', 2016, 9, 10, NULL, NULL, NULL, 'day', '10 September 2016', 37, 'https://en.wikipedia.org/wiki/2016_Tanzania_earthquake'),
  ('Q66363820', 'Morogoro tanker explosion', 'This is a list of notable tank truck fires and explosions.', 2019, 8, 10, NULL, NULL, NULL, 'day', '10 August 2019', 48, 'https://en.wikipedia.org/wiki/Morogoro_tanker_explosion'),
  ('Q115102751', 'Precision Air Flight 494', 'Precision Air Flight 494 was a scheduled domestic passenger flight within Tanzania, from Julius Nyerere International Airport to Bukoba Airport via Mwanza Airport. On 6 November 2022, the ATR 42-500 plane crashed in Lake Victoria while attempting to land at Bukoba during bad weather and low visibility.', 2022, 11, 6, NULL, NULL, NULL, 'day', '6 November 2022', 61, 'https://en.wikipedia.org/wiki/Precision_Air_Flight_494'),
  ('Q118316106', '2023 Africa floods', 'From February to late-December 2023, floods killed over 2,600 people in 15 countries across Africa.', 2023, 2, 5, NULL, NULL, NULL, 'day', '5 February 2023', 43, 'https://en.wikipedia.org/wiki/2023_Africa_floods'),
  ('Q136682955', '2025 Tanzanian election protests', 'A series of demonstrations and civil unrest began in Tanzania on 29 October 2025 amid the country''s 2025 general election. The protests erupted in Dar es Salaam and later spread to other cities, following allegations of electoral irregularities, suppression of opposition parties, and police intimidation.', 2025, 10, 29, NULL, NULL, NULL, 'day', '29 October 2025', 43, 'https://en.wikipedia.org/wiki/2025_Tanzanian_election_protests');
